// One item per term to extract, all asked about the contract that was just indexed.
const documentId = $input.first().json.document_id;
const checklist = {
  salary: 'Kolika je osnovna mesečna zarada?',
  probation: 'Koliko traje probni rad?',
  annualLeave: 'Koliko dana godišnjeg odmora ima zaposleni?',
  noticePeriod: 'Koliki je otkazni rok kada zaposleni da otkaz?',
  remoteWork: 'Da li zaposleni može da radi od kuće i koliko dana?',
};
return Object.entries(checklist).map(([key, question]) => ({ json: { key, question, documentId } }));

// Fold the checklist answers into one row. Anything not found goes to needsReview
// instead of a guessed value, so a person checks those fields.
const indexed = $('Index contract').first().json;
const asked = $('Checklist questions').all();
const row = {
  indexedAt: $now.toISO(),
  file: indexed.filename,
  documentId: indexed.document_id,
  alreadyIndexed: indexed.duplicate,
};
const needsReview = [];
$input.all().forEach((item, i) => {
  const key = asked[i].json.key;
  row[key] = item.json.answered ? item.json.answer.replace(/\s*\[\d+\]/g, '') : '';
  if (!item.json.answered) needsReview.push(key);
});
row.needsReview = needsReview.join(', ');
return [{ json: row }];
